import {toolCatalog,toolGroups,toolAvailability} from './tool-catalog.mjs?v=20261028-hub2';
export function installToolHub(api){
 const {$}=api,panel=document.querySelector('.task-panel');
 panel.insertAdjacentHTML('beforeend',`<div id="common-tools" class="common-tools" aria-label="常用工具"></div><details id="tool-catalog" class="tool-catalog"><summary>所有功能與狀態 <span id="tool-total"></span></summary><div class="tool-catalog-heading"><label for="tool-query">找工具</label><input id="tool-query" type="search" maxlength="100" placeholder="例如：改字、合併、OCR、備份"><p id="tool-availability" class="field-hint" role="status"></p></div><div id="tool-groups" class="tool-groups"></div><p id="tool-no-results" class="field-hint" hidden>沒有符合的功能，試試「文字」「PDF」或「備份」。</p><p class="field-hint">依目前文件與勾選頁顯示可用狀態。點入口後可繼續設定；文件只在這台裝置處理。</p></details>`);
 const controls=[],groups=[];
 for(const [key,label]of Object.entries(toolGroups)){const section=document.createElement('section'),heading=document.createElement('h3'),list=document.createElement('div');section.className='tool-group';section.dataset.toolGroup=key;heading.textContent=label;list.className='tool-list';section.append(heading,list);$('tool-groups').append(section);groups.push(section);
  for(const tool of toolCatalog.filter(t=>t.group===key)){const card=document.createElement('article'),title=document.createElement('strong'),description=document.createElement('p'),status=document.createElement('span'),button=document.createElement('button');card.className='tool-card';card.dataset.feature=tool.id;title.textContent=tool.label;description.textContent=tool.description;status.className='tool-state';status.id='tool-state-'+tool.id;button.type='button';button.className='secondary';button.textContent='開啟';button.setAttribute('aria-label','開啟'+tool.label);button.setAttribute('aria-describedby',status.id);button.onclick=()=>void activate(tool);card.append(title,description,status,button);list.append(card);controls.push({tool,card,status,button});}
 }
 for(const id of ['native','capture','impose','pdf-preview']){const tool=toolCatalog.find(t=>t.id===id),button=document.createElement('button'),title=document.createElement('strong'),status=document.createElement('span');button.type='button';button.className='secondary common-tool';button.dataset.shortcut=id;title.textContent=tool.label;status.className='tool-state';button.append(title,status);button.onclick=()=>void activate(tool);$('common-tools').append(button);controls.push({tool,status,button});}
 $('tool-total').textContent=`${toolCatalog.length} 項`;
 function state(){return{busy:api.isBusy(),dialog:!!document.querySelector('dialog[open]'),pages:api.getPages().length,selected:api.chosen().length,sources:api.getSources().size,images:!$('image-results').hidden};}
 function availability(tool){const el=document.querySelector(tool.selector);return toolAvailability(tool,state(),{exists:!!el,disabled:!!el?.matches(':disabled')});}
 function reveal(el){for(let p=el;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;el.scrollIntoView({block:'center',behavior:'instant'});const control=el.matches('input,button,select,textarea,[tabindex]')?el:el.querySelector('summary,input,select,button');control?.focus({preventScroll:true});el.classList.add('tool-located');setTimeout(()=>el.classList.remove('tool-located'),1800);}
 async function activate(tool){const current=availability(tool);if(!current.ready){api.toast(current.label);refresh();return;}if(tool.task)api.showTask(tool.task);try{const el=document.querySelector(tool.selector),record=api.chosen()[0];if(['native','replace','text'].includes(tool.action))await api.openMarks(record,tool.action);else if(tool.action==='crop')await api.openCrop(record);else if(tool.action==='click')el.click();else reveal(el);}catch{api.status('工具暫時無法開啟，請重試；目前文件已保留。',true);}finally{refresh();}}
 function filter(){const value=$('tool-query').value.normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,'');let shown=0;for(const {tool,card}of controls){if(!card)continue;const haystack=(tool.label+toolGroups[tool.group]+(tool.keywords||'')).normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,'');card.hidden=!!value&&!haystack.includes(value);shown+=!card.hidden;}for(const section of groups)section.hidden=![...section.querySelectorAll('.tool-card')].some(c=>!c.hidden);$('tool-no-results').hidden=shown>0;}
 function refresh(){const current=state();let ready=0;for(const {tool,status,button,card}of controls){const value=availability(tool);button.disabled=!value.ready;const label=value.ready&&['native','replace','text','crop'].includes(tool.action)?`開啟第 ${api.getPages().indexOf(api.chosen()[0])+1} 頁`:value.label;if(status.textContent!==label)status.textContent=label;status.dataset.ready=String(value.ready);if(card&&value.ready)ready++;}const note=current.busy?(current.dialog?'工具視窗已開啟，完成或取消後可切換。':'正在處理文件，完成或停止後可繼續操作。'):`目前可開啟 ${ready}／${toolCatalog.length} 項 · 已勾選 ${current.selected}／${current.pages} 頁`;$('tool-availability').textContent=note;$('common-tools').hidden=document.querySelector('[data-task][aria-pressed=true]')?.dataset.task!=='all';}
 $('tool-query').addEventListener('input',filter);$('tool-catalog').addEventListener('toggle',refresh);
 // Move existing nodes: handlers, IDs, settings and saved data stay attached.
 document.querySelector('.settings').append(document.querySelector('.project-panel'),document.querySelector('.template-panel'));
 refresh();return{refresh};
}
